="<?= (int)$item['is_active']===1?'0':'1' ?>"><button class="admin-quiet-button" type="submit" data-confirm="¿Confirmas el cambio de estado?"><?= (int)$item['is_active']===1?'Desactivar':'Activar' ?></button></form><?php endif?></td></tr><?php endforeach?></tbody></table></div><?php endif?>
